create table ledger_accounts (kind varchar(20) primary key check(kind in ('INCOME','PETTY','CLOUD','BULK')),balance numeric(18,2) not null default 0,units bigint not null default 0 check(units>=0),version bigint not null default 0,check(kind<>'PETTY' or balance>=0));
insert into ledger_accounts(kind) values ('INCOME'),('PETTY'),('CLOUD'),('BULK');
create table ledger_entries (id bigint generated by default as identity primary key,kind varchar(20) not null references ledger_accounts(kind),transaction_date date not null,description varchar(1000) not null,category varchar(100) not null,reference varchar(100) not null,payment_mode varchar(30) not null,amount_delta numeric(14,2) not null,units_delta bigint not null default 0,client_id bigint references saccos(id),actor_id bigint not null references users(id),request_key uuid not null,payload_hash varchar(64) not null,reversal_of bigint unique references ledger_entries(id),balance_after numeric(18,2) not null,units_after bigint not null check(units_after>=0),created_at timestamptz not null default current_timestamp,unique(actor_id,kind,request_key),check(amount_delta<>0 or units_delta<>0),check(kind='BULK' or units_delta=0));
create index ledger_kind_date_idx on ledger_entries(kind,transaction_date desc,id desc);
create function protect_ledger_entry() returns trigger language plpgsql as $$ begin raise exception 'Posted ledger entries are immutable'; end $$;
create trigger ledger_immutable before update or delete on ledger_entries for each row execute function protect_ledger_entry();
alter table expenses add column version bigint not null default 0,add column request_key uuid,add column approved_by bigint references users(id),add column reviewed_at timestamptz,add column review_comment varchar(1000) not null default '',add column payment_reference varchar(100) not null default '',add column reversed_by bigint references users(id),add column reversed_at timestamptz;
create unique index expenses_actor_request_uq on expenses(user_id,request_key) where request_key is not null;
